import java.util.concurrent.atomic.AtomicLong;

public class ShortCodes {
    static final String ALPHABET = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";

    static String encode(long id) {
        if (id == 0) return "0";
        StringBuilder sb = new StringBuilder();
        while (id > 0) {
            sb.append(ALPHABET.charAt((int) (id % 62)));
            id /= 62;
        }
        return sb.reverse().toString();
    }

    static long decode(String code) {
        long v = 0;
        for (char c : code.toCharArray()) v = v * 62 + ALPHABET.indexOf(c);
        return v;
    }

    /** Hands out blocks of ids; in production this is one row in a database or a ZooKeeper counter. */
    static class BlockAllocator {
        private final AtomicLong next = new AtomicLong(0);
        long[] nextBlock(int size) {
            long start = next.getAndAdd(size);
            return new long[] {start, start + size};
        }
    }

    /** One app server: takes a block, then serves ids from memory without any network call. */
    static class IdSource {
        private final BlockAllocator allocator;
        private final int blockSize;
        private long current, end;
        int blocksFetched = 0;

        IdSource(BlockAllocator allocator, int blockSize) { this.allocator = allocator; this.blockSize = blockSize; }

        synchronized long next() {
            if (current == end) {
                long[] b = allocator.nextBlock(blockSize);
                current = b[0];
                end = b[1];
                blocksFetched++;
            }
            return current++;
        }
    }

    /** A bijection on 0..2^42-1 so that consecutive ids do not give consecutive codes (multiply by an odd number, mod 2^42). */
    static final long MASK = (1L << 42) - 1;
    static final long ODD = 0x2545F4914F6L | 1;
    static long scramble(long id) { return (id * ODD) & MASK; }

    public static void main(String[] args) {
        System.out.println("encode(0)=" + encode(0) + " encode(61)=" + encode(61) + " encode(62)=" + encode(62));
        System.out.println("encode(125)=" + encode(125) + " decode back=" + decode(encode(125)));
        long max7 = (long) Math.pow(62, 7);
        System.out.println("codes with 7 characters: " + max7);
        System.out.println("a 42-bit id is at most " + encode(MASK).length() + " characters");

        BlockAllocator allocator = new BlockAllocator();
        IdSource server = new IdSource(allocator, 1000);
        long last = -1;
        for (int i = 0; i < 2500; i++) last = server.next();
        System.out.println("2500 ids needed " + server.blocksFetched + " blocks, last id " + last);

        System.out.println("sequential ids 1000,1001,1002 -> " + encode(scramble(1000)) + " " + encode(scramble(1001)) + " " + encode(scramble(1002)));
        java.util.Set<Long> seen = new java.util.HashSet<>();
        boolean unique = true;
        for (long i = 0; i < 100_000; i++) unique &= seen.add(scramble(i));
        System.out.println("100000 scrambled ids all distinct: " + unique);
    }
}

