        for entry in self.data:
            if entry[0] == key:
                entry[1] = value
                entry[2] = self.timer
                return
        if len(self.data) == self.cap:
            oldest_idx = 0
            for i in range(1, len(self.data)):
                if self.data[i][2] < self.data[oldest_idx][2]:
                    oldest_idx = i
            self.data.pop(oldest_idx)
        self.data.append([key, value, self.timer])

